   284	      hostname: hostname(),
   285	      command: 'provider-process-registry mutation',
   286	      acquiredAt: new Date().toISOString(),
   287	      lockId: randomUUID(),
   288	      processStartTimeMs: currentProcessStartTimeMs(),
   289	    },
