   320	    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
   321	    if (live.length >= boundedCap) return null;
   322	    const token = randomUUID();
   323	    const record: ProviderProcessSlotFileMeta = { ...meta, token };
   324	    for (let index = 0; index < boundedCap; index += 1) {
   325	      const file = join(dir, `slot-${index}.json`);
   326	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
