   419	    const occupant = readSlotOccupant(file);
   420	    if (occupant.state !== 'valid' || occupant.token !== token) return false;
   421	    const next: ProviderProcessSlotFileMeta = {
   422	      ...(occupant.meta as unknown as ProviderProcessSlotFileMeta),
   423	      pid: identity.pid,
